import os, glob, re
def load_grids():
    d = os.path.normpath(os.environ['RLM_SESSION_DIR'])
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read().replace('\\n', '\n')
    grids = []
    for m in re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t):
        k, h, w = m[1], int(m[2]), int(m[3])
        lines = [line.strip() for line in t[m.end():].split('\n')[:h]]
        if len(lines) == h and all(len(line) == w and all(c.isdigit() for c in line) for line in lines):
            grids.append({k: [[int(c) for c in line] for line in lines]})
        else:
            grids.append(None)
    return grids

globs = load_grids()
print("Available grids:", [k for k in globs[0].keys()] if globs[0] else "Nil")
if globs[0]:
    for k, grid in globs[0].items():
        print(f"\n{k} ({len(grid)}x{len(grid[0])}):")
        for row in grid: print(" ".join(str(c) for c in row))

